const raw = await helpers.getBinaryDataBuffer(0, "data");
const token = raw.length <= 128 * 1024 ? Buffer.from(raw).toString("utf8") : "";
return [
  { json: { token: /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(token) ? token : "" } },
];

function dialpadCallId(value) {
  const text = typeof value === "number" && Number.isSafeInteger(value) ? String(value) : value;
  if (
    typeof text !== "string" ||
    !/^[1-9]\d{0,18}$/.test(text) ||
    BigInt(text) > 9223372036854775807n
  ) {
    throw new Error(
      "Call IDs must be exact positive integers. Store them as plain text in Sheets.",
    );
  }
  return text;
}

function dialpadEvent(token, verified) {
  const segments = token.split(".");
  if (
    verified?.header?.alg !== "HS256" ||
    !verified.payload ||
    segments.length !== 3 ||
    verified.signature !== segments[2]
  ) {
    return {
      needsLookup: false,
      statusCode: 401,
      response: { error: "Invalid Dialpad signature" },
    };
  }
  const source = new TextDecoder("utf-8", { fatal: true }).decode(
    Buffer.from(segments[1], "base64url"),
  );
  const event = JSON.parse(source, (key, value, context) => {
    if (key === "call_id" && typeof value === "number" && /^\d+$/.test(context?.source ?? ""))
      return context.source;
    return value;
  });
  if (event.state !== "hangup") return { needsLookup: false, statusCode: 200, response: [] };
  const timestamp = (raw) => {
    const value = typeof raw === "string" && /^\d{1,15}$/.test(raw) ? Number(raw) : raw;
    if (!Number.isSafeInteger(value) || value < 0 || value > 8640000000000000)
      throw new Error("Invalid call timestamp");
    return value;
  };
  const callId = dialpadCallId(event.call_id);
  const start = timestamp(event.date_started);
  const end = timestamp(event.date_ended);
  if (end < start) throw new Error("Call end precedes its start");
  const text = (value, max) =>
    typeof value === "string"
      ? value
          .replace(/[\x00-\x1f\x7f]/g, " ")
          .trim()
          .slice(0, max)
      : "";
  const name = text(event.contact?.name, 200);
  const phone = text(event.contact?.phone, 80);
  const contact = name && phone ? name + " (" + phone + ")" : name || phone;
  const order = {
    start_at: new Date(start).toISOString(),
    end_at: new Date(end).toISOString(),
    notes: contact ? "Phone call from " + contact + "." : "Phone call.",
  };
  return { needsLookup: true, callId, order };
}

function syncroTimerSettings(data) {
  const { spreadsheetId, tab, syncroSubdomain, userId } = data;
  if (
    typeof spreadsheetId !== "string" ||
    !/^[A-Za-z0-9_-]{12,}$/.test(spreadsheetId) ||
    spreadsheetId.startsWith("YOUR_") ||
    typeof tab !== "string" ||
    !tab.trim() ||
    tab.length > 100
  )
    throw new Error("Configure the Google Sheets spreadsheet and tab");
  if (
    typeof syncroSubdomain !== "string" ||
    !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(syncroSubdomain) ||
    syncroSubdomain === "your-subdomain"
  )
    throw new Error("Configure your Syncro subdomain");
  if (!Number.isSafeInteger(userId) || userId < 1)
    throw new Error("Configure the Syncro technician User ID");
  return {
    sheetUrl:
      "https://sheets.googleapis.com/v4/spreadsheets/" +
      spreadsheetId +
      "/values/" +
      encodeURIComponent("'" + tab.replace(/'/g, "''") + "'!A:B") +
      "?majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE",
    origin: "https://" + syncroSubdomain + ".syncromsp.com",
    userId,
  };
}

const settings = {
  spreadsheetId: "YOUR_SPREADSHEET_ID",
  tab: "Call Tickets",
  syncroSubdomain: "your-subdomain",
  userId: 0,
};
const verified = $input.first().json;
const { token } = $("Read the compact JWT").first().json;
let mapped;
try {
  mapped = dialpadEvent(token, verified);
} catch {
  return [
    {
      json: {
        needsLookup: false,
        statusCode: 400,
        response: { error: "Invalid Dialpad ended-call data" },
      },
    },
  ];
}
if (!mapped.needsLookup) return [{ json: mapped }];
return [
  { json: { ...mapped, callKey: "dialpad:" + mapped.callId, ...syncroTimerSettings(settings) } },
];

const rows = $input.all();
if (rows.length === 1 && !Object.keys(rows[0].json).length) return [{ json: { unreserved: true } }];
const row = rows[0]?.json;
const { callKey } = $("Read the ended call").first().json;
if (rows.length !== 1 || row.call_key !== callKey || !/^[1-9]\d*$/.test(row.ticket_id ?? "")) {
  throw new Error("The Dialpad call reservation is inconsistent");
}
if (row.status === "pending")
  return [
    {
      json: {
        unreserved: false,
        statusCode: 202,
        response: { status: "pending", ticket_id: row.ticket_id },
      },
    },
  ];
if (row.status !== "confirmed") throw new Error("Unknown Dialpad call reservation status");
const receipt = JSON.parse(row.receipt);
if (
  !Number.isSafeInteger(receipt?.id) ||
  receipt.id < 1 ||
  String(receipt.ticket_id) !== row.ticket_id
) {
  throw new Error("The saved timer does not belong to the reserved ticket");
}
return [{ json: { unreserved: false, statusCode: 200, response: [receipt] } }];

function dialpadCallId(value) {
  const text = typeof value === "number" && Number.isSafeInteger(value) ? String(value) : value;
  if (
    typeof text !== "string" ||
    !/^[1-9]\d{0,18}$/.test(text) ||
    BigInt(text) > 9223372036854775807n
  ) {
    throw new Error(
      "Call IDs must be exact positive integers. Store them as plain text in Sheets.",
    );
  }
  return text;
}

function matchSyncroTicket(values, callId) {
  if (!Array.isArray(values) || !Array.isArray(values[0]))
    throw new Error("The mapping tab needs Call and Ticket column headers");
  const headers = values[0];
  if (
    headers.filter((key) => key === "Call").length !== 1 ||
    headers.filter((key) => key === "Ticket").length !== 1
  ) {
    throw new Error("The mapping tab needs one Call column and one Ticket column");
  }
  const call = headers.indexOf("Call");
  const ticket = headers.indexOf("Ticket");
  const targets = [];
  for (const row of values.slice(1)) {
    if (!Array.isArray(row)) throw new Error("Google Sheets returned an invalid mapping row");
    if (row[call] == null || row[call] === "") continue;
    if (dialpadCallId(row[call]) === callId) targets.push(row[ticket]);
  }
  if (targets.length > 1) {
    return {
      shouldWrite: false,
      statusCode: 409,
      response: { error: "The Call ID has multiple ticket mappings" },
    };
  }
  const target = targets[0];
  if (target == null || target === "") return { shouldWrite: false, statusCode: 200, response: [] };
  const text = typeof target === "string" ? target : String(target);
  const ticketId = Number(text);
  if (!/^[1-9]\d*$/.test(text) || !Number.isSafeInteger(ticketId))
    throw new Error("The mapped Syncro Ticket ID is invalid");
  return { shouldWrite: true, ticketId };
}

const event = $("Read the ended call").first().json;
const found = matchSyncroTicket($input.first().json.values, event.callId);
if (!found.shouldWrite) return [{ json: found }];
return [
  {
    json: {
      ...found,
      url: event.origin + "/api/v1/tickets/" + found.ticketId + "/timer_entry",
      order: { ...event.order, user_id: event.userId },
    },
  },
];

const rows = $input.all();
const row = rows[0]?.json;
const match = $("Find the matching ticket").first().json;
if (
  rows.length !== 1 ||
  row.call_key !== $("Read the ended call").first().json.callKey ||
  row.ticket_id !== String(match.ticketId) ||
  row.status !== "pending"
) {
  throw new Error("The intended Syncro ticket was not reserved");
}
return [{ json: match }];

function syncroTimerReceipt(statusCode, timer, expected) {
  if (
    statusCode !== 200 ||
    !Number.isSafeInteger(timer?.id) ||
    timer.id < 1 ||
    timer.ticket_id !== expected.ticketId ||
    timer.user_id !== expected.order.user_id ||
    Date.parse(timer.start_time) !== Date.parse(expected.order.start_at) ||
    Date.parse(timer.end_time) !== Date.parse(expected.order.end_at)
  ) {
    return {
      statusCode: 502,
      response: { error: "Syncro did not confirm this timer. Check the ticket before retrying." },
    };
  }
  return { statusCode: 200, response: [timer] };
}

const expected = $("Find the matching ticket").first().json;
const { body, statusCode } = $input.first().json;
const result = syncroTimerReceipt(statusCode, body, expected);
if (result.statusCode !== 200) return [{ json: result }];
const { id, ticket_id, user_id, start_time, end_time } = result.response[0];
return [
  { json: { statusCode: 200, response: [{ id, ticket_id, user_id, start_time, end_time }] } },
];

const rows = $input.all();
const row = rows[0]?.json;
if (
  rows.length !== 1 ||
  row.call_key !== $("Read the ended call").first().json.callKey ||
  row.ticket_id !== String($("Find the matching ticket").first().json.ticketId) ||
  row.status !== "confirmed" ||
  row.receipt !== JSON.stringify($("Confirm the matching timer").first().json.response[0])
)
  throw new Error("Syncro timer receipt was not saved");
return [{ json: $("Confirm the matching timer").first().json }];
